dialog.addEventListener('click', (e) => {
  const rect = dialog.getBoundingClientRect();
  const isBackdropClick = e.clientX < rect.left || e.clientX > rect.right || e.clientY < rect.top || e.clientY > rect.bottom;
  if (isBackdropClick) dialog.close();
});

/* Class sr-only chuẩn Tailwind */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

// CI/CD Playwright kết hợp Axe-core
import AxeBuilder from '@axe-core/playwright';
test('WCAG 2.1 AA compliance', async ({ page }) => {
  await page.goto('/');
  const results = await new AxeBuilder({ page })
    .withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa'])
    .analyze();
  expect(results.violations).toEqual([]);
});
